// Pick Due Clip: chooses and claims AT MOST ONE clip per execution.
// Schedule: every 15 min, 12:00-20:45 SAST. One clip per slot (12:00, 15:00,
// 18:00), newest manifest first, YouTube-sourced jobs only. Returning []
// stops the run. Canonical source: scripts/pick-due-clip.jsCode.js; the
// workflow JSON is generated from it (scripts/build-workflow.js).
//
// n8n 2.x Code-node sandbox: luxon is the global `DateTime` (requiring the
// luxon package aborts the runner) and only fs/path/crypto may be required.
const fs = require('fs');
const path = require('path');

const DRY_RUN = true; // deploy-workflow.sh --live flips this in memory, never in git

const TZ = 'Africa/Johannesburg';
const DATA_ROOT = '/data/reelsmith-inbox';             // PVC root, outside the Syncthing folder
const INBOX = path.join(DATA_ROOT, 'reelsmith-inbox'); // Syncthing folder; the sidecar's /inbox
const SLOT_DIR = path.join(DATA_ROOT, '.slots');
const STATE_DIR = path.join(DATA_ROOT, '.state');
const STATE_FILE = path.join(STATE_DIR, 'retryable-failures.json'); // shared with Log Results
const NOTICES_FILE = path.join(STATE_DIR, 'notices.json');           // details for a human
const SLOTS = ['12:00', '15:00', '18:00'];
const MIN_GAP_MIN = 170;    // since the newest slot marker's claimedAt
const LAST_CALL = '21:00';  // no catch-up at or after this time
const STALE_CLAIM_MIN = 30; // a claim with no outcome after this is released
const CUTOFF = '2026-10-11';  // manifests modified before this day (SAST) are ignored
const MIN_BYTES = 1024;       // a clip of 1 KB or less is junk
const MAX_CLIP_MB = 300;      // the sidecar's MAX_CLIP_MB: anything larger gets a 413
const TIMEOUT_BASE_S = 240;   // sidecar: timeout_s = 240 + ceil(1.5 * size_MiB)
const TIMEOUT_PER_MIB_S = 1.5;
const HTTP_MARGIN_S = 60;
const MAX_TIMEOUT_MS = 780000; // must stay under the workflow's executionTimeout (900 s)
// A subset of the sidecar's rule (tiktok-sidecar/sidecar/clip.py FILENAME_RE
// `[\w. -]{1,251}\.mp4`, Python \w = letters, digits, underscore; no leading
// dot; at most 255 bytes), capped at 200 bytes so `<name>.json` and every
// derived path stay far below NAME_MAX.
const NAME_RE = /^(?!\.)[\p{L}\p{N}_. -]{1,251}\.mp4$/u;
const MAX_NAME_BYTES = 200;
const NAME_MAX = 255; // a longer spelling (an NFD name grows) cannot exist on disk: never lstat it
// Jobs exported before manifest.csv had a `source` column, confirmed YouTube-sourced.
const YOUTUBE_LEGACY_JOBS = [
  '1979f8a4a33643b5a43d8f0fb4337d3e',
  '851cbce7386b47959c6136cc3fa9758e',
  'd7a54c8aa4454fc38949927c0e5c9505',
  '32508a2a96a14ce38cd087bfb1fdeb22',
  '48ac096bd9db4976a06f63be654a2900',
];
const JOB_RE = /^[A-Za-z0-9_-]+$/;

const now = DateTime.now().setZone(TZ);
const today = now.toISODate();
const execId = (typeof $execution !== 'undefined' && $execution && $execution.id) ? String($execution.id) : 'manual';

function lstatOrNull(p) {
  try {
    return fs.lstatSync(p);
  } catch (e) {
    if (e && e.code === 'ENOENT') return null;
    throw e;
  }
}

// lstat, never stat: a symlinked .claims/.slots would redirect writes elsewhere.
function ensureRealDir(p) {
  try {
    fs.mkdirSync(p);
  } catch (e) {
    if (!e || e.code !== 'EEXIST') throw e;
  }
  const st = fs.lstatSync(p);
  if (!st.isDirectory()) throw new Error('Pick Due Clip: not a real directory: ' + p);
}

function at(hhmm) {
  const [hour, minute] = hhmm.split(':').map(Number);
  return now.startOf('day').set({ hour, minute });
}

function readClaimedAt(file) {
  try {
    const parsed = DateTime.fromISO(String(JSON.parse(fs.readFileSync(file, 'utf8')).claimedAt || ''));
    if (parsed.isValid) return parsed;
  } catch (e) {
    // unreadable or half-written: fall back to the file's mtime below
  }
  const st = lstatOrNull(file);
  return st ? DateTime.fromMillis(st.mtimeMs) : null;
}

// A missing inbox means Syncthing's folder was renamed or unmounted: fail the
// run (the watchdog sees errors) instead of reporting "nothing to post".
function listJobs() {
  const st = lstatOrNull(INBOX);
  if (!st || !st.isDirectory()) throw new Error('Pick Due Clip: inbox missing or not a directory: ' + INBOX);
  return fs.readdirSync(INBOX).filter((n) => {
    if (!JOB_RE.test(n)) return false;
    const st = lstatOrNull(path.join(INBOX, n));
    return Boolean(st && st.isDirectory());
  });
}

// RFC 4180: quoted fields may hold commas, doubled quotes and newlines.
function parseCsv(text) {
  const records = [];
  let row = [];
  let cell = '';
  let quoted = false;
  let i = text.charCodeAt(0) === 0xfeff ? 1 : 0;
  for (; i < text.length; i++) {
    const ch = text[i];
    if (quoted) {
      if (ch === '"') {
        if (text[i + 1] === '"') { cell += '"'; i++; } else quoted = false;
      } else cell += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === ',') { row.push(cell); cell = ''; }
    else if (ch === '\r' || ch === '\n') {
      if (ch === '\r' && text[i + 1] === '\n') i++;
      row.push(cell); records.push(row); row = []; cell = '';
    } else cell += ch;
  }
  if (quoted) throw new Error('unterminated quoted field');
  if (cell !== '' || row.length) { row.push(cell); records.push(row); }
  const nonBlank = records.filter((r) => !(r.length === 1 && r[0].trim() === ''));
  if (!nonBlank.length) throw new Error('empty manifest');
  const header = nonBlank[0].map((h) => h.trim());
  if (!header.includes('filename')) throw new Error('manifest has no filename column');
  const rows = nonBlank.slice(1).map((cells) => {
    const o = {};
    header.forEach((h, idx) => { o[h] = cells[idx] === undefined ? '' : cells[idx]; });
    return o;
  });
  return { header, rows };
}

// The sidecar's caption cleaning (tiktok-sidecar/sidecar/caption.py clean_body):
// drop URLs, non-BMP characters, invisibles, @ and #. Conservative: "empty" only
// when what is left is whitespace to both Python and JS, and the URL match stops
// at any character either side calls whitespace, so n8n never junks a caption
// the sidecar would accept (a wrong "usable" only costs a 400).
const BLANK_RE = /^[\t\n\v\f\r \u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]*$/u;
const BLANK_EDGES_RE = /^[\t\n\v\f\r \u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+|[\t\n\v\f\r \u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+$/gu;
// String.prototype.trim also eats U+FEFF, which the sidecar keeps.
const trimBlank = (text) => String(text == null ? '' : text).replace(BLANK_EDGES_RE, '');
const URL_RE = /(?:https?:\/\/|www\.)[^\s\x1c-\x1f\x85]*/giu;
function captionUsable(text) {
  const body = String(text == null ? '' : text)
    .replace(URL_RE, ' ')
    .replace(/[\u{10000}-\u{10FFFF}]/gu, '')
    .replace(/[\x00-\x08\x0b-\x1f\x7f\u200d\ufe0e\ufe0f]/g, '')
    .replace(/[@#]/g, '');
  return !BLANK_RE.test(body);
}

// -> {kind: 'junk'|'missing'|'claimed'|'ready', ...}. Names are NFC; the on-disk
// name may be NFD (copied from macOS), so NFC is tried first, then NFD.
// junk.notice: a real clip that can never be posted as it is. It is reported
// (manifestErrors, a daily alert) and pins its manifest until a human acts.
function inspectClip(jobDir, rawName) {
  const name = String(rawName == null ? '' : rawName);
  if (!name.trim()) return { kind: 'junk', reason: 'empty filename' };
  const nfc = name.normalize('NFC');
  if (!nfc.endsWith('.mp4')) return { kind: 'junk', reason: 'not .mp4' };
  // Path safety first: nothing below may touch a path outside this job folder.
  if (nfc !== path.basename(nfc) || nfc.startsWith('.') || /[\\/\0]/.test(nfc)) {
    return { kind: 'junk', reason: 'unsafe filename', notice: true };
  }
  if (Buffer.byteLength(nfc, 'utf8') > MAX_NAME_BYTES) return { kind: 'junk', reason: 'name over 200 bytes', notice: true };
  if (!NAME_RE.test(nfc)) return { kind: 'junk', reason: 'name the sidecar refuses', notice: true };
  let diskName = null;
  let st = null;
  for (const candidate of [...new Set([nfc, name.normalize('NFD'), name])]) {
    if (Buffer.byteLength(candidate, 'utf8') > NAME_MAX) continue;
    st = lstatOrNull(path.join(jobDir, candidate));
    if (st) { diskName = candidate; break; }
  }
  if (!st) return { kind: 'missing', nfc };
  if (!st.isFile()) return { kind: 'junk', reason: 'not a regular file', notice: true };
  if (st.size <= MIN_BYTES) return { kind: 'junk', reason: '1 KB or less' };
  if (st.size > MAX_CLIP_MB * 1048576) return { kind: 'junk', reason: `over ${MAX_CLIP_MB} MiB`, notice: true };
  const claimPath = path.join(jobDir, '.claims', nfc + '.json');
  if (lstatOrNull(claimPath)) return { kind: 'claimed', nfc };
  return { kind: 'ready', nfc, diskName, size: st.size, claimPath };
}

function hashtagsField(raw) {
  const s = String(raw == null ? '' : raw).trim();
  if (!s) return '[]';
  try {
    const parsed = JSON.parse(s);
    if (Array.isArray(parsed)) return JSON.stringify(parsed.map(String));
  } catch (e) {
    // not JSON: Contract v1 also accepts whitespace/comma separated tags
  }
  // The sidecar 400s anything that starts like a JSON array but is not one:
  // post without tags rather than set the clip aside.
  return s.startsWith('[') ? '[]' : s;
}

// 1. Stale-claim sweep. Only our own unresolved claims (status 'claimed') are
// released; outcomes and the pre-2026-10 workflow's markers (no status) stay.
// A released clip that did reach TikTok gets a 409 from the sidecar ledger.
// ponytail: the crashed run's slot marker is NOT released, so a crash costs
//   that slot (at most 3 a day); the safe direction for an upload that may
//   have posted.
for (const job of listJobs()) {
  const claimDir = path.join(INBOX, job, '.claims');
  const dirSt = lstatOrNull(claimDir);
  if (!dirSt || !dirSt.isDirectory()) continue;
  for (const name of fs.readdirSync(claimDir)) {
    if (!name.endsWith('.json')) continue;
    const file = path.join(claimDir, name);
    let claim;
    try {
      claim = JSON.parse(fs.readFileSync(file, 'utf8'));
    } catch (e) {
      continue; // being written right now, or not ours
    }
    if (!claim || claim.status !== 'claimed') continue;
    const claimedAt = readClaimedAt(file);
    if (claimedAt && now.diff(claimedAt, 'minutes').minutes > STALE_CLAIM_MIN) {
      fs.rmSync(file, { force: true });
    }
  }
}

// 2. Slot gate (real runs only). A dry run may run at any time and takes no slot.
let slot = null;
if (!DRY_RUN) {
  if (now >= at(LAST_CALL)) return [];
  ensureRealDir(SLOT_DIR);
  const markerPath = (day, i) => path.join(SLOT_DIR, `${day}-${i}.json`);
  const due = SLOTS.findIndex((s, i) => at(s) <= now && !lstatOrNull(markerPath(today, i)));
  if (due < 0) return [];
  // ponytail: markers are never pruned (3 small files a day); only today's and
  // yesterday's are read, since the gap is far shorter than a day.
  const recentDays = [today, now.minus({ days: 1 }).toISODate()];
  let newest = null;
  for (const name of fs.readdirSync(SLOT_DIR)) {
    if (!name.endsWith('.json') || !recentDays.some((d) => name.startsWith(d + '-'))) continue;
    const claimedAt = readClaimedAt(path.join(SLOT_DIR, name));
    if (claimedAt && (!newest || claimedAt > newest)) newest = claimedAt;
  }
  if (newest && now.diff(newest, 'minutes').minutes < MIN_GAP_MIN) return [];
  slot = { index: due, date: today, marker: markerPath(today, due) };
}

// 3. Candidates: every non-archived manifest.csv modified on/after CUTOFF,
// newest first, rows in file order.
const cutoffMs = DateTime.fromISO(CUTOFF, { zone: TZ }).toMillis();
const manifests = [];
for (const job of listJobs()) {
  const manifestPath = path.join(INBOX, job, 'manifest.csv');
  const st = lstatOrNull(manifestPath);
  if (!st || !st.isFile() || st.mtimeMs < cutoffMs) continue;
  manifests.push({ job, jobDir: path.join(INBOX, job), manifestPath, mtimeMs: st.mtimeMs });
}
manifests.sort((a, b) => (b.mtimeMs - a.mtimeMs) || (a.job < b.job ? -1 : a.job > b.job ? 1 : 0));

function writeStateAtomic(file, obj) {
  ensureRealDir(STATE_DIR);
  const tmp = path.join(STATE_DIR, `.tmp-pick-${execId.replace(/[^A-Za-z0-9_-]/g, '').slice(0, 32)}-${now.toMillis()}`);
  fs.writeFileSync(tmp, JSON.stringify(obj, null, 2) + '\n', { flag: 'wx' });
  fs.renameSync(tmp, file);
}

function readState() {
  try {
    return JSON.parse(fs.readFileSync(STATE_FILE, 'utf8')) || {};
  } catch (e) {
    return {};
  }
}

// 4. Scan EVERY row of every candidate manifest first, so problems anywhere are
// reported even when an earlier row gets posted. errors: the unexpected ones
// (unreadable manifest, a row that threw). notices: clips that can never be
// posted as they are. manifestErrors (both) goes to Log Results' daily alert.
const errors = [];
const notices = [];
const candidates = [];
for (const m of manifests) {
  let parsed;
  try {
    parsed = parseCsv(fs.readFileSync(m.manifestPath, 'utf8'));
  } catch (e) {
    errors.push(m.job + ': ' + String((e && e.message) || e).slice(0, 120));
    continue;
  }
  // YouTube only: with a `source` column every row must say youtube (an empty
  // cell counts only for a confirmed legacy job: its DB source is NULL); without
  // the column, the job must be on the confirmed legacy list. Everything else
  // is skipped and therefore never archived.
  const hasSource = parsed.header.includes('source');
  const legacyJob = YOUTUBE_LEGACY_JOBS.includes(m.job);
  if (!hasSource && !legacyJob) continue;

  for (let rowIndex = 0; rowIndex < parsed.rows.length; rowIndex++) {
    const row = parsed.rows[rowIndex];
    const source = String(row.source).trim();
    if (hasSource && source !== 'youtube' && !(source === '' && legacyJob)) continue;
    const where = `${m.job} row ${rowIndex + 1}`;
    // One bad row never stops the others: an unexpected error (EACCES, EIO, ...)
    // skips that row for this run.
    let clip;
    try {
      clip = inspectClip(m.jobDir, row.filename);
    } catch (e) {
      errors.push(`${where}: ${(e && e.code) || 'error'}`);
      continue;
    }
    if (clip.kind === 'junk' && clip.notice) notices.push(`${where}: ${clip.reason}`);
    if (clip.kind !== 'ready') continue; // junk: skip; missing: wait for Syncthing; claimed: skip
    const title = trimBlank(row.title);
    const caption = captionUsable(row.description) ? trimBlank(row.description) : title;
    if (!captionUsable(caption)) {
      notices.push(`${where}: no usable caption`);
      continue;
    }
    candidates.push({ m, rowIndex, row, clip, title, caption });
  }
}
const manifestErrors = [...errors, ...notices];
if (notices.length || lstatOrNull(NOTICES_FILE)) {
  writeStateAtomic(NOTICES_FILE, { updatedAt: now.toISO(), notices });
}

// 5. Claim the first candidate nobody else holds.
for (const { m, rowIndex, row, clip, title, caption } of candidates) {
  const timeoutMs = (TIMEOUT_BASE_S + Math.ceil(TIMEOUT_PER_MIB_S * clip.size / 1048576) + HTTP_MARGIN_S) * 1000;
  if (timeoutMs > MAX_TIMEOUT_MS) {
    throw new Error(`Pick Due Clip: timeout ${timeoutMs} ms exceeds ${MAX_TIMEOUT_MS} ms; lower MAX_CLIP_MB or raise executionTimeout`);
  }

  // Claim = <jobDir>/.claims/<NFC filename>.json; it is never removed for a
  // posted, needs_you or failed clip. Recover a stuck clip by deleting its
  // claim (unpublished-inventory.js lists them).
  // ponytail: O_EXCL is atomic on this single-node local PVC; on NFS or a
  //   multi-node volume, move claims to a Postgres UNIQUE row.
  ensureRealDir(path.join(m.jobDir, '.claims'));
  const clipKey = `${m.job}/${clip.nfc}`;
  try {
    fs.writeFileSync(clip.claimPath, JSON.stringify({
      status: 'claimed',
      claimedAt: now.toISO(),
      execId,
      clip_key: clipKey,
      dryRun: DRY_RUN,
      slot: slot ? { date: slot.date, index: slot.index } : null,
    }) + '\n', { flag: 'wx' }); // O_EXCL: a concurrent run that got here first wins
  } catch (e) {
    if (e && e.code === 'EEXIST') continue;
    throw e;
  }
  if (slot) {
    try {
      fs.writeFileSync(slot.marker, JSON.stringify({
        claimedAt: now.toISO(),
        execId,
        clip_key: clipKey,
      }) + '\n', { flag: 'wx' });
    } catch (e) {
      fs.rmSync(clip.claimPath, { force: true });
      if (e && e.code === 'EEXIST') return []; // another run took this slot: stand down
      throw e;
    }
  }

  return [{
    json: {
      clip_path: clipKey,
      clip_key: clipKey,
      caption,
      hashtags: hashtagsField(row.hashtags),
      dryRun: DRY_RUN,
      timeoutMs,
      manifestPath: m.manifestPath,
      jobDir: m.jobDir,
      rowIndex,
      filename: clip.nfc,
      title,
      sizeBytes: clip.size,
      claimPath: clip.claimPath,
      slotMarker: slot ? slot.marker : null,
      claimedAt: now.toISO(),
      manifestErrors,
    },
  }];
}

// 6. Nothing to post. An unexpected error fails every run so the watchdog
// reports it. Clips that can never be posted fail ONE run a SAST day (the day
// is recorded first), so an idle dispatcher is not silent about them either;
// the list is in .state/notices.json.
if (errors.length) {
  throw new Error('Pick Due Clip: unreadable manifest(s) or row(s): ' + errors.join('; '));
}
if (notices.length) {
  const state = readState();
  if (state.idleNoticeDay !== today) {
    writeStateAtomic(STATE_FILE, { ...state, idleNoticeDay: today });
    throw new Error(`Pick Due Clip: ${notices.length} clip(s) can never be posted as they are; see .state/notices.json (reported once a day)`);
  }
}
return [];

// Log Results: turns the sidecar's answer into ONE outcome for the picked clip.
// Order matters: the claim (and slot) are settled on disk BEFORE any alert, so
// a failed Telegram send can never leave a clip half-recorded; the send
// failure then fails the run so the watchdog sees it. Canonical source:
// scripts/log-results.jsCode.js.
const fs = require('fs');
const path = require('path');

const TZ = 'Africa/Johannesburg';
const DATA_ROOT = '/data/reelsmith-inbox';
const INBOX = path.join(DATA_ROOT, 'reelsmith-inbox');
const STATE_DIR = path.join(DATA_ROOT, '.state');
const RETRY_STATE = path.join(STATE_DIR, 'retryable-failures.json');
const RETRY_ALERT_AFTER = 3;    // consecutive retryable failures before the first alert
const AUTH_ALERT_AFTER = 1;     // consecutive auth_invalid answers before the first alert
const REALERT_EVERY = 12;       // then one more alert per 12 in a row (about 3h at */15)
const NEEDS_SLOT_RELEASES = 2;  // needs_you frees the slot only for the first 2 in a row
// Names are at most 200 UTF-8 bytes (Pick Due Clip), so even the longest alert,
// which repeats the name in two ledger commands and the claim-release command,
// stays under this cap (Telegram's own limit is 4096).
const ALERT_MAX_CHARS = 2000;
const HEADER = 'timestamp,filename,title,tiktok_post_id,tiktok_post_url,youtube_video_id,youtube_status,error,tiktok_status\n';
// Failures before the request left n8n: connect and DNS errors. Anything later
// (read ETIMEDOUT, read EHOSTUNREACH, ECONNRESET, EPIPE, the HTTP timeout) may
// have posted. These codes count on their own only when there is no message.
const RETRYABLE_CODES = ['ECONNREFUSED', 'EHOSTUNREACH', 'ENETUNREACH', 'EHOSTDOWN', 'ENOTFOUND', 'EAI_AGAIN'];
const JOB_RE = /^[A-Za-z0-9_-]{1,64}$/;
const NAME_RE = /^(?!\.)[\p{L}\p{N}_. -]{1,251}\.mp4$/u; // as Pick Due Clip
const MAX_NAME_BYTES = 200;
const SSH_EXEC = "ssh homelab 'microk8s kubectl -n n8n-live exec deploy/n8n-application-worker --";

const pick = $('Pick Due Clip').first().json;
const res = $input.first().json || {};
const now = DateTime.now().setZone(TZ);
const today = now.toISODate();
const helpers = this.helpers;
const execId = (typeof $execution !== 'undefined' && $execution && $execution.id) ? String($execution.id) : 'manual';

const safeCode = (v) => (typeof v === 'string' && /^[a-z0-9_]{1,40}$/.test(v) ? v : '');
const safeErrorId = (v) => (typeof v === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(v) ? v : '');

function parseBody(body) {
  if (body && typeof body === 'object') return body;
  if (typeof body === 'string') {
    try {
      const parsed = JSON.parse(body);
      if (parsed && typeof parsed === 'object') return parsed;
    } catch (e) {
      // not JSON: classified by HTTP status alone
    }
  }
  return {};
}

// continueOnFail turns a transport failure into {error: <AxiosError JSON>}.
// Classified by PHASE: Node's connect/DNS errors read "connect <ERRNO> ..." or
// "getaddrinfo <ERRNO> ..." and never sent the request, so they are retried.
// Everything after that may have reached the sidecar: ambiguous. axios's own
// timeout is ECONNABORTED, "timeout of <n>ms exceeded" (n8n does not set
// clarifyTimeoutError).
function transportFailure(err) {
  const e = (err && typeof err === 'object') ? err : { message: String(err) };
  const code = String(e.code || (e.cause && e.cause.code) || '').toUpperCase();
  const message = String(e.message || e.description || '');
  if (/^(connect|getaddrinfo) /.test(message) || (!message && RETRYABLE_CODES.includes(code))) {
    return { kind: 'retryable', code: safeCode(code.toLowerCase()) || 'connect_error' };
  }
  if (code === 'ECONNABORTED' || /timeout of \d+ms exceeded/i.test(message)) {
    return { kind: 'ambiguous', code: 'timeout' };
  }
  return { kind: 'ambiguous', code: safeCode(code.toLowerCase()) || 'request_error' };
}

// -> {kind, status?, code, errorId, httpStatus}
//    kind: posted | posted_elsewhere | dry_run | daily_cap | retryable | auth_invalid
//          | needs_you (definitely not uploaded, this clip is set aside) | ambiguous (may have posted)
function classify(r) {
  if (r.statusCode === undefined && r.error !== undefined) {
    return { ...transportFailure(r.error), errorId: '', httpStatus: null };
  }
  const httpStatus = Number(r.statusCode);
  const body = parseBody(r.body);
  const code = safeCode(body.code);
  const errorId = safeErrorId(body.error_id);
  const out = (kind, fallback) => ({ kind, code: code || fallback, errorId, httpStatus });
  if (httpStatus === 200) {
    if (body.status === 'success' && body.code === 'posted') return out('posted', 'posted');
    if (body.status === 'dry_run') return out('dry_run', 'dry_run');
    return out('ambiguous', 'unexpected_200');
  }
  if (httpStatus === 409) return code === 'duplicate' ? out('posted_elsewhere', 'duplicate') : out('needs_you', 'ambiguous');
  if (httpStatus === 401) return out('auth_invalid', 'auth_invalid');
  if (httpStatus === 400) return out('needs_you', 'bad_input');
  if (httpStatus === 413) return out('needs_you', 'too_large');
  if (httpStatus === 429) return out('daily_cap', 'daily_cap');
  if (httpStatus === 503) return out('retryable', 'unavailable');
  // 500 internal, 502 publish_rejected/signature_failed, 504 timeout, anything unexpected
  return out('ambiguous', 'http_' + (Number.isFinite(httpStatus) ? httpStatus : 'unknown'));
}

function lstatOrNull(p) {
  try {
    return fs.lstatSync(p);
  } catch (e) {
    if (e && e.code === 'ENOENT') return null;
    throw e;
  }
}

function assertRealDir(dir) {
  const st = lstatOrNull(dir);
  if (!st || !st.isDirectory()) throw new Error('Log Results: not a real directory: ' + dir);
}

// lstat the directory, write a fresh tmp (O_EXCL, so a planted symlink is
// never followed), then rename over the target: readers see old or new, never half.
function writeJsonAtomic(file, obj) {
  const dir = path.dirname(file);
  assertRealDir(dir);
  // Short on purpose: a name derived from the clip's would exceed NAME_MAX.
  const tmp = path.join(dir, `.tmp-${execId.replace(/[^A-Za-z0-9_-]/g, '').slice(0, 32)}-${now.toMillis()}`);
  fs.writeFileSync(tmp, JSON.stringify(obj, null, 2) + '\n', { flag: 'wx' });
  fs.renameSync(tmp, file);
}

function csvEscape(v) {
  const s = String(v == null ? '' : v);
  return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}

function appendResultRow(jobDir, cells) {
  assertRealDir(jobDir);
  const logPath = path.join(jobDir, 'results.log.csv');
  try {
    fs.writeFileSync(logPath, HEADER, { flag: 'wx' });
  } catch (e) {
    if (!e || e.code !== 'EEXIST') throw e;
  }
  const st = fs.lstatSync(logPath);
  if (!st.isFile()) throw new Error('Log Results: results.log.csv is not a regular file');
  fs.appendFileSync(logPath, cells.map(csvEscape).join(',') + '\n');
}

async function sendAlert(text) {
  const token = $env.TELEGRAM_BOT_TOKEN;
  const chatId = $env.TELEGRAM_CHAT_ID;
  if (!token || !chatId) throw new Error('Log Results: alert not sent, TELEGRAM_BOT_TOKEN/TELEGRAM_CHAT_ID unset');
  try {
    await helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${token}/sendMessage`,
      json: true,
      timeout: 10000,
      body: { chat_id: chatId, text: text.slice(0, ALERT_MAX_CHARS), disable_web_page_preview: true },
    });
  } catch (e) {
    // Never echo e.message: it can carry the request URL, and with it the bot token.
    const why = safeCode(String((e && (e.code || e.httpCode)) || '').toLowerCase()) || 'send_failed';
    throw new Error('Log Results: Telegram alert failed (' + why + '); the outcome is already recorded');
  }
}

const outcome = classify(res);

// Consecutive-outcome counters: sidecar unavailable (count), TikTok session
// invalid (authCount), clip refused as needs_you (needsCount, today only, so
// an old streak never blocks a later day). Any other outcome resets each to 0.
fs.mkdirSync(STATE_DIR, { recursive: true });
let state = {};
try {
  state = JSON.parse(fs.readFileSync(RETRY_STATE, 'utf8')) || {};
} catch (e) {
  state = {};
}
const retryCount = outcome.kind === 'retryable' ? (Number(state.count) || 0) + 1 : 0;
const authCount = outcome.kind === 'auth_invalid' ? (Number(state.authCount) || 0) + 1 : 0;
const needsCount = outcome.kind === 'needs_you'
  ? (state.needsDay === today ? Number(state.needsCount) || 0 : 0) + 1 : 0;

// Released clips are retried by a later run: nothing reached TikTok (retryable,
// auth_invalid, dry run) or today's cap was hit. A dry run never uploads, so even
// a "needs you" answer (e.g. simulate=auth_invalid) releases the clip there. A
// real "posted" is always kept, whatever the mode.
const releaseClip = ['retryable', 'auth_invalid', 'dry_run', 'daily_cap'].includes(outcome.kind)
  || (pick.dryRun === true && ['needs_you', 'ambiguous'].includes(outcome.kind));
// The slot stays used when an upload may have reached TikTok (posted,
// ambiguous) or the daily cap is hit; a definite "not uploaded" frees it for
// the next 15-minute run. needs_you frees it only for the first 2 in a row, so
// a systematic refusal sets aside at most 5 clips a day (2 + the 3 slots).
const releaseSlot = ['retryable', 'auth_invalid', 'dry_run', 'posted_elsewhere'].includes(outcome.kind)
  || (outcome.kind === 'needs_you' && needsCount <= NEEDS_SLOT_RELEASES)
  || (pick.dryRun === true && outcome.kind !== 'posted');
const claimStatus = {
  posted: 'posted', posted_elsewhere: 'posted_elsewhere', needs_you: 'needs_you', ambiguous: 'failed',
}[outcome.kind];
const rowStatus = releaseClip ? outcome.kind : claimStatus;

// 1. Settle the claim and the slot on disk.
if (releaseClip) {
  assertRealDir(path.dirname(pick.claimPath));
  fs.rmSync(pick.claimPath, { force: true });
} else {
  writeJsonAtomic(pick.claimPath, {
    status: claimStatus,
    claimedAt: pick.claimedAt,
    decidedAt: now.toISO(),
    execId,
    clip_key: pick.clip_key,
    code: outcome.code,
    error_id: outcome.errorId,
    http_status: outcome.httpStatus,
    dryRun: pick.dryRun === true,
  });
}
if (releaseSlot && pick.slotMarker) {
  assertRealDir(path.dirname(pick.slotMarker));
  fs.rmSync(pick.slotMarker, { force: true });
}

// 2. Persist the consecutive-outcome counters computed above.
const counters = {
  ...state, // keeps the once-a-day markers (Pick Due Clip writes idleNoticeDay here)
  count: retryCount,
  authCount,
  needsCount,
  needsDay: today,
  lastCode: outcome.code,
  updatedAt: now.toISO(),
};
writeJsonAtomic(RETRY_STATE, counters);

// 3. One row per outcome in the job's results.log.csv (live column order; the
// TikTok outcome goes in the trailing tiktok_status column). A file that still
// has the old 8-column header keeps it; unpublished-inventory.js reads the 9th cell.
appendResultRow(pick.jobDir, [
  now.toISO(),
  pick.filename,
  pick.title,
  '',
  '',
  '',
  '',
  [outcome.code, outcome.errorId].filter(Boolean).join(' '),
  rowStatus,
]);

// 4. Alert last. Fixed strings + code + error_id + filename (and the claim
// path built from the validated job id and filename) only: never the caption
// or any other sidecar output.
const line = (label, v) => (v ? `\n${label}: ${v}` : '');
const detail = `${line('code', outcome.code)}${line('error_id', outcome.errorId)}${line('file', pick.filename)}`;
const due = (n, first) => n >= first && (n - first) % REALERT_EVERY === 0;

function releaseSteps(withLedger) {
  if (pick.dryRun === true) return ''; // a dry run already released its claim
  const job = path.basename(String(pick.jobDir || ''));
  const file = String(pick.filename || '');
  if (!JOB_RE.test(job) || !NAME_RE.test(file) || Buffer.byteLength(file, 'utf8') > MAX_NAME_BYTES) {
    return '\nThen delete the clip\'s claim file under .claims/ in its job folder to let n8n retry it.';
  }
  // NAME_RE allows no quote, so single quotes keep a name with spaces one KEY.
  const key = `'${job}/${file}'`;
  const release = `${SSH_EXEC} rm "${INBOX}/${job}/.claims/${file}.json"'`;
  if (!withLedger) {
    return `\n1. Fix the clip (re-export it), or leave it set aside.\n2. To let n8n retry it, release the n8n claim:\n${release}`;
  }
  return '\n1. Check TikTok, then in tiktok-sidecar run the line that matches:'
    + `\nmake ledger-resolve KEY=${key} OUTCOME=posted`
    + `\nmake ledger-resolve KEY=${key} OUTCOME=not_posted`
    + '\nIf it is refused with "no ledger rows" or "it is free", the upload never reached TikTok: go to 2.'
    + '\n2. Release the n8n claim (the clip is retried; one resolved as posted comes back as a 409 duplicate and its manifest archives):'
    + `\n${release}`;
}

// safety: the run fails if these cannot be sent. info: once-a-day notices; a
// failed send is logged and retried by the next run (its day stays unmarked).
const safety = [];
const info = [];
const infoDays = {};
if (outcome.kind === 'auth_invalid' && due(authCount, AUTH_ALERT_AFTER)) {
  safety.push(`🔑 Reelsmith: TikTok session invalid (${authCount} in a row). Run \`make refresh-cookies\` in tiktok-sidecar; clips wait and retry every 15 min.` + detail);
} else if (outcome.kind === 'needs_you') {
  safety.push((outcome.code === 'ambiguous'
    ? 'Reelsmith: a clip is blocked by an earlier upload that may have posted (it will not be retried).'
    : 'Reelsmith: a clip was refused (not posted, will not be retried).')
    + (needsCount > NEEDS_SLOT_RELEASES ? '\n3+ clips refused in a row: check the sidecar contract.' : '')
    + detail + releaseSteps(outcome.code === 'ambiguous'));
} else if (outcome.kind === 'ambiguous') {
  safety.push('Reelsmith: upload outcome unknown (it may have posted).' + detail + releaseSteps(true));
} else if (outcome.kind === 'retryable' && due(retryCount, RETRY_ALERT_AFTER)) {
  safety.push(`Reelsmith: sidecar unavailable ${retryCount} times in a row; clips are waiting.` + detail);
}
// Unusable manifests or clips Pick Due Clip reported: once per SAST day, a count only.
const manifestIssues = Array.isArray(pick.manifestErrors) ? pick.manifestErrors.length : 0;
if (manifestIssues > 0 && counters.manifestAlertDay !== today) {
  info.push(`Reelsmith: ${manifestIssues} manifest problem(s) (an unreadable manifest, or clips that can never be posted as they are); see .state/notices.json or the Pick Due Clip output in today's n8n executions.`);
  infoDays.manifestAlertDay = today;
}
// The kill switch is off while the workflow runs live: every clip is released
// and retried every 15 min, so say so once a day.
if (outcome.kind === 'dry_run' && outcome.code === 'posting_disabled' && pick.dryRun !== true
  && counters.postingDisabledAlertDay !== today) {
  info.push('Reelsmith: the sidecar has POSTING_ENABLED=false while the workflow is live; clips are released and retried every 15 min.');
  infoDays.postingDisabledAlertDay = today;
}
const parts = [...safety, ...info];
const alertText = parts.length ? (pick.dryRun === true ? '[dry run] ' : '') + parts.join('\n\n') : null;
if (alertText) {
  let sent = false;
  try {
    await sendAlert(alertText);
    sent = true;
  } catch (e) {
    if (safety.length) throw e;
    console.log('Log Results: informational alert not sent; the next run retries it. ' + e.message);
  }
  if (sent && info.length) writeJsonAtomic(RETRY_STATE, { ...counters, ...infoDays });
}

return [{
  json: {
    clip_key: pick.clip_key,
    filename: pick.filename,
    manifestPath: pick.manifestPath,
    jobDir: pick.jobDir,
    dryRun: pick.dryRun === true,
    outcome: outcome.kind,
    status: rowStatus,
    code: outcome.code,
    error_id: outcome.errorId,
    httpStatus: outcome.httpStatus,
    clipReleased: releaseClip,
    slotReleased: Boolean(releaseSlot && pick.slotMarker),
    retryCount,
    authCount,
    needsCount,
    alerted: Boolean(alertText),
  },
}];

// Archive Manifest: moves the picked clip's manifest.csv into processed/ once
// EVERY row is done: posted, posted_elsewhere or ordinary junk (empty filename,
// not .mp4, 1 KB or less). A missing clip (Syncthing still copying), a failed
// or needs-you clip, a clip Pick Due Clip reports as never postable (refused
// name, over 300 MiB, no usable caption, not a regular file), a row that
// cannot be checked, or a row from a non-YouTube source keeps the manifest
// where it is. Canonical source: scripts/archive-manifest.jsCode.js.
const fs = require('fs');
const path = require('path');

const TZ = 'Africa/Johannesburg';
const DONE = ['posted', 'posted_elsewhere'];
// Junk rules, kept identical to Pick Due Clip (workflow-contract.selfcheck.js compares them).
const MIN_BYTES = 1024;       // a clip of 1 KB or less is junk
const MAX_CLIP_MB = 300;      // the sidecar's MAX_CLIP_MB: anything larger gets a 413
const NAME_RE = /^(?!\.)[\p{L}\p{N}_. -]{1,251}\.mp4$/u;
const MAX_NAME_BYTES = 200;
const NAME_MAX = 255; // a longer spelling (an NFD name grows) cannot exist on disk: never lstat it

const pick = $('Pick Due Clip').first().json;
const items = $input.all();
const now = DateTime.now().setZone(TZ);

function lstatOrNull(p) {
  try {
    return fs.lstatSync(p);
  } catch (e) {
    if (e && e.code === 'ENOENT') return null;
    throw e;
  }
}

// Same RFC 4180 reader as Pick Due Clip (quoted commas, quotes and newlines).
function parseCsv(text) {
  const records = [];
  let row = [];
  let cell = '';
  let quoted = false;
  let i = text.charCodeAt(0) === 0xfeff ? 1 : 0;
  for (; i < text.length; i++) {
    const ch = text[i];
    if (quoted) {
      if (ch === '"') {
        if (text[i + 1] === '"') { cell += '"'; i++; } else quoted = false;
      } else cell += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === ',') { row.push(cell); cell = ''; }
    else if (ch === '\r' || ch === '\n') {
      if (ch === '\r' && text[i + 1] === '\n') i++;
      row.push(cell); records.push(row); row = []; cell = '';
    } else cell += ch;
  }
  if (quoted) throw new Error('unterminated quoted field');
  if (cell !== '' || row.length) { row.push(cell); records.push(row); }
  const nonBlank = records.filter((r) => !(r.length === 1 && r[0].trim() === ''));
  if (!nonBlank.length) throw new Error('empty manifest');
  const header = nonBlank[0].map((h) => h.trim());
  if (!header.includes('filename')) throw new Error('manifest has no filename column');
  const rows = nonBlank.slice(1).map((cells) => {
    const o = {};
    header.forEach((h, idx) => { o[h] = cells[idx] === undefined ? '' : cells[idx]; });
    return o;
  });
  return { header, rows };
}

// The sidecar's caption cleaning (tiktok-sidecar/sidecar/caption.py clean_body):
// drop URLs, non-BMP characters, invisibles, @ and #. Conservative: "empty" only
// when what is left is whitespace to both Python and JS, and the URL match stops
// at any character either side calls whitespace, so n8n never junks a caption
// the sidecar would accept (a wrong "usable" only costs a 400).
const BLANK_RE = /^[\t\n\v\f\r \u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]*$/u;
const BLANK_EDGES_RE = /^[\t\n\v\f\r \u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+|[\t\n\v\f\r \u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+$/gu;
// String.prototype.trim also eats U+FEFF, which the sidecar keeps.
const trimBlank = (text) => String(text == null ? '' : text).replace(BLANK_EDGES_RE, '');
const URL_RE = /(?:https?:\/\/|www\.)[^\s\x1c-\x1f\x85]*/giu;
function captionUsable(text) {
  const body = String(text == null ? '' : text)
    .replace(URL_RE, ' ')
    .replace(/[\u{10000}-\u{10FFFF}]/gu, '')
    .replace(/[\x00-\x08\x0b-\x1f\x7f\u200d\ufe0e\ufe0f]/g, '')
    .replace(/[@#]/g, '');
  return !BLANK_RE.test(body);
}

// The same rules as Pick Due Clip. Ordinary junk is done; a clip Pick reports
// (a notice) is NOT: it pins the manifest until a human fixes the clip or
// archives the manifest by hand. Otherwise done only if the claim records a
// posted outcome.
function rowDone(jobDir, row) {
  const name = String(row.filename == null ? '' : row.filename);
  if (!name.trim()) return true;
  const nfc = name.normalize('NFC');
  if (!nfc.endsWith('.mp4')) return true;
  if (nfc !== path.basename(nfc) || nfc.startsWith('.') || /[\\/\0]/.test(nfc)) return false;
  if (Buffer.byteLength(nfc, 'utf8') > MAX_NAME_BYTES || !NAME_RE.test(nfc)) return false;
  let st = null;
  for (const candidate of [...new Set([nfc, name.normalize('NFD'), name])]) {
    if (Buffer.byteLength(candidate, 'utf8') > NAME_MAX) continue;
    st = lstatOrNull(path.join(jobDir, candidate));
    if (st) break;
  }
  if (!st) return false; // missing: wait, never archive
  if (!st.isFile() || st.size > MAX_CLIP_MB * 1048576) return false;
  if (st.size <= MIN_BYTES) return true;
  if (!captionUsable(row.description) && !captionUsable(row.title)) return false;
  try {
    const claim = JSON.parse(fs.readFileSync(path.join(jobDir, '.claims', nfc + '.json'), 'utf8'));
    return Boolean(claim && DONE.includes(claim.status));
  } catch (e) {
    return false; // no claim yet, or unreadable
  }
}

// A row that cannot be checked (EIO, EACCES, ...) keeps the manifest: keeping
// it costs one rescan, archiving it would drop a clip nobody was told about.
function rowDoneSafe(jobDir, row) {
  try {
    return rowDone(jobDir, row);
  } catch (e) {
    return false;
  }
}

const passthrough = items.map((it) => ({ json: it.json }));
const manifestPath = pick.manifestPath;
const jobDir = pick.jobDir;
if (!manifestPath || !jobDir || path.dirname(manifestPath) !== jobDir) return passthrough;
const st = lstatOrNull(manifestPath);
if (!st || !st.isFile()) return passthrough;

const { rows } = parseCsv(fs.readFileSync(manifestPath, 'utf8'));
if (!rows.every((r) => rowDoneSafe(jobDir, r))) return passthrough;

const processed = path.join(jobDir, 'processed');
try {
  fs.mkdirSync(processed);
} catch (e) {
  if (!e || e.code !== 'EEXIST') throw e;
}
if (!fs.lstatSync(processed).isDirectory()) throw new Error('Archive Manifest: processed/ is not a real directory');
const dest = path.join(processed, `manifest-${now.toUTC().toISO().replace(/[:.]/g, '-')}.csv`);
fs.renameSync(manifestPath, dest);
return items.map((it) => ({ json: { ...it.json, archived_to: dest } }));
